// The charts of the streaming writer: `worksheet.addChart` (a chart in the drawing of a streamed worksheet) and
// `writer.addChartsheet` (a chartsheet). The options are validated by the code of the document charts
// (src/doc/chart.ts validateChart), and the chart part is generated by the same code (chartModel), when the workbook is
// committed: the drawings, the chartsheets and the chart parts are written after every worksheet, so that a chart may show
// the data of a worksheet committed after its own.
//
// The cached values: the rows of a streamed worksheet are dropped once written. When a chart is added, each of its ranges
// is registered with the worksheet of its data (a RangeCapture), and the values of its cells are captured as the rows are
// written: the rows still in memory are captured when they are committed. The values of the rows committed before the
// chart was added are not known: a series with such a range (a committed row, or a committed worksheet) is written with
// its formulas only, without any cache (`<c:numCache>` / `<c:strCache>` are optional in CT_NumRef / CT_StrRef): Excel
// and LibreOffice draw it from the cells, a viewer that does not recalculate shows it empty. A whole series rather than
// the ranges not known: a partial cache would show names or categories without their values. The other series are
// captured. Nothing else is kept:
// - memory: a capture holds the values of the non-empty cells of its range only (one row or one column of the grid: at
//   most 1,048,576 cells per range, and a chart has up to 765 ranges), stored compactly (doc/chart.ts ChartRangeValues:
//   typed arrays, about 13 bytes per number, no object per cell), released once the chart part is generated;
// - time: each worksheet keeps its captures in a heap by first row; as the rows are written in order, a capture becomes
//   active at its first row and is dropped after its last one: writing a row costs one look per active capture, plus the
//   cells of the ranges it holds (linear in the rows written and the cells captured).

import type Row from "../../doc/row";
import { ChartRangeValues, chartModel, seriesRanges, type ChartDefinition, type ChartRange } from "../../doc/chart";
import type { ChartType } from "../../../index";
import type { ChartAnchorModel } from "../../types";

/** What a chart of the streaming writer needs from a worksheet of its data. */
export interface CapturedSheet {
    readonly name: string;
    /** @returns whether the cells of a range of the worksheet can be captured: none of its rows is committed */
    _canCaptureChartRange(range: ChartRange<CapturedSheet>): boolean;
    /**
     * Registers a range of the worksheet (its rows not written yet): its values are captured as its rows are written.
     * @returns the capture
     */
    _captureChartRange(range: ChartRange<CapturedSheet>): RangeCapture;
}

/** The values of the cells of a range, captured as its rows are written: the non-empty cells, by index in the range. */
export class RangeCapture {
    /** The first row of the range (1-based). */
    readonly top: number;
    /** The last row of the range. */
    readonly bottom: number;
    private readonly left: number;
    private readonly right: number;
    // the cells with a value, by increasing index: the rows are captured in order, each one once
    private readonly data: ChartRangeValues;
    private isReleased = false;

    constructor(range: { readonly top: number; readonly left: number; readonly bottom: number; readonly right: number }) {
        this.top = range.top;
        this.left = range.left;
        this.bottom = range.bottom;
        this.right = range.right;
        // the streaming writer has no date1904 setting
        this.data = new ChartRangeValues((this.bottom - this.top + 1) * (this.right - this.left + 1), false);
    }

    /** Captures the cells of the range in a row being written (a row of the range). */
    capture(row: Row): void {
        const width = this.right - this.left + 1;
        const base = (row.number - this.top) * width - this.left;
        for (let col = this.left; col <= this.right; col++) {
            this.data.addCell(base + col, row.findCell(col));
        }
    }

    /** True once the chart no longer needs the values (removed, or written): the capture is dropped. */
    get released(): boolean {
        return this.isReleased;
    }

    /** Drops the values captured, and stops capturing. */
    release(): void {
        this.isReleased = true;
        this.data.clear();
    }

    /** The values of the cells of the range captured (the cells empty, or of rows not written, have no point). */
    values(): ChartRangeValues {
        return this.data;
    }
}

/** The captures of the ranges of a worksheet: they capture its rows as they are written, in order. */
export class SheetCaptures {
    // the captures not active yet: a binary min-heap by first row
    private readonly pending: RangeCapture[] = [];
    // the captures whose first row was written
    private active: RangeCapture[] = [];

    /** Adds a capture (its first row not written yet). */
    add(capture: RangeCapture): void {
        const heap = this.pending;
        heap.push(capture);
        let index = heap.length - 1;
        while (index > 0) {
            const parent = (index - 1) >> 1;
            const above = heap[parent];
            if (!above || above.top <= capture.top) {
                break;
            }
            heap[index] = above;
            heap[parent] = capture;
            index = parent;
        }
    }

    /** Removes the first capture of the heap. */
    private pop(): void {
        const heap = this.pending;
        const last = heap.pop();
        if (!last || !heap.length) {
            return;
        }
        heap[0] = last;
        let index = 0;
        for (;;) {
            const left = 2 * index + 1;
            const right = left + 1;
            let smallest = index;
            const leftItem = heap[left];
            const rightItem = heap[right];
            if (leftItem && leftItem.top < (heap[smallest]?.top ?? Infinity)) {
                smallest = left;
            }
            if (rightItem && rightItem.top < (heap[smallest]?.top ?? Infinity)) {
                smallest = right;
            }
            if (smallest === index) {
                return;
            }
            const child = heap[smallest];
            if (!child) {
                return;
            }
            heap[smallest] = last;
            heap[index] = child;
            index = smallest;
        }
    }

    /** Captures the cells of a row being written (the rows are written in increasing order). */
    capture(row: Row): void {
        const { number } = row;
        for (let next = this.pending[0]; next && next.top <= number; next = this.pending[0]) {
            this.pop();
            if (!next.released) {
                this.active.push(next);
            }
        }
        if (!this.active.length) {
            return;
        }
        const kept: RangeCapture[] = [];
        for (const capture of this.active) {
            if (capture.released || capture.bottom < number) {
                continue;
            }
            capture.capture(row);
            if (capture.bottom > number) {
                kept.push(capture);
            }
        }
        this.active = kept;
    }
}

/** A chart of the streaming writer once validated, with the captures of its ranges. */
export class CapturedChart {
    /** The chart validated. */
    readonly definition: ChartDefinition<CapturedSheet>;
    private readonly captures = new Map<ChartRange<CapturedSheet>, RangeCapture>();

    /**
     * Registers the ranges of a chart validated with the worksheets of their data: those of each series whose ranges can
     * all be captured (the others are written without cache).
     */
    constructor(definition: ChartDefinition<CapturedSheet>) {
        this.definition = definition;
        for (const item of definition.series) {
            const ranges = [...seriesRanges(item)];
            if (ranges.every((range) => range.sheet._canCaptureChartRange(range))) {
                for (const range of ranges) {
                    this.captures.set(range, range.sheet._captureChartRange(range));
                }
            }
        }
    }

    /**
     * The anchor and the chart part of the chart, its cached values those captured (every worksheet committed): a series
     * not captured has no cache. The captures are released.
     * @param name - the name of its graphic frame (`Chart 1`)
     */
    toModel(name: string): ChartAnchorModel {
        const model = chartModel(this.definition, name, (range) => this.captures.get(range)?.values(), false);
        this.release();
        return model;
    }

    /** Releases the captures: their worksheets stop capturing the values of the chart. */
    release(): void {
        for (const capture of this.captures.values()) {
            capture.release();
        }
    }
}

/** What a chart of a streamed worksheet needs from its worksheet. */
export interface ChartHostSheet {
    /** True once the worksheet is committed. */
    readonly committed: boolean;
    /** Removes a chart of the worksheet (not committed). */
    _removeChart(chart: WorksheetWriterChart): void;
}

/** A chart of a streamed worksheet (`worksheet.addChart`): written with the worksheet's drawing when the workbook is committed. */
export class WorksheetWriterChart {
    /** The type of the chart. */
    readonly type: ChartType;
    /** The chart validated, with the captures of its ranges. */
    readonly _chart: CapturedChart;
    private readonly host: ChartHostSheet;

    constructor(host: ChartHostSheet, chart: CapturedChart) {
        this.host = host;
        this._chart = chart;
        this.type = chart.definition.type;
    }

    /** The title of the chart. */
    get title(): string | undefined {
        return this._chart.definition.title;
    }

    /**
     * Removes the chart from its worksheet.
     * @throws Error once the worksheet is committed (its drawing is written)
     */
    remove(): void {
        if (this.host.committed) {
            throw new Error("Invalid Operation: the worksheet has been committed");
        }
        this.host._removeChart(this);
        this._chart.release();
    }
}
